CREATE TABLE IF NOT EXISTS hr_shift_attendance(attendance_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,employee_id TEXT NOT NULL,work_date DATE NOT NULL,shift_code TEXT,scheduled_hours NUMERIC NOT NULL DEFAULT 0,worked_hours NUMERIC NOT NULL DEFAULT 0,overtime_hours NUMERIC NOT NULL DEFAULT 0,absent BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'POSTED',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,employee_id,work_date));
CREATE TABLE IF NOT EXISTS hr_workforce_incentive_rule(rule_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,rule_name TEXT NOT NULL,basis TEXT NOT NULL DEFAULT 'OUTPUT',threshold NUMERIC NOT NULL DEFAULT 0,rate NUMERIC NOT NULL DEFAULT 0,max_amount NUMERIC,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,rule_name));
CREATE TABLE IF NOT EXISTS hr_workforce_incentive(incentive_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_id TEXT NOT NULL,employee_id TEXT NOT NULL,production_batch_id TEXT,basis_value NUMERIC NOT NULL DEFAULT 0,incentive_amount NUMERIC NOT NULL DEFAULT 0,rule_id TEXT,status TEXT NOT NULL DEFAULT 'CALCULATED',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_workforce_performance_snapshot(snapshot_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_id TEXT NOT NULL,employee_id TEXT NOT NULL,attendance_days INTEGER NOT NULL DEFAULT 0,scheduled_hours NUMERIC NOT NULL DEFAULT 0,worked_hours NUMERIC NOT NULL DEFAULT 0,overtime_hours NUMERIC NOT NULL DEFAULT 0,output_qty NUMERIC NOT NULL DEFAULT 0,labour_cost NUMERIC NOT NULL DEFAULT 0,output_per_hour NUMERIC NOT NULL DEFAULT 0,labour_cost_per_unit NUMERIC NOT NULL DEFAULT 0,attendance_rate NUMERIC NOT NULL DEFAULT 0,productivity_index NUMERIC NOT NULL DEFAULT 0,incentive_amount NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'READY',generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,period_id,employee_id));
CREATE TABLE IF NOT EXISTS hr_workforce_performance_close(close_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'CLOSED',closed_by TEXT NOT NULL,closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,period_id));
